const P=k=>PS[k];
/* [skill, passage, the question, the right choice, wrong choices, why] */
const ROWS=[
 ['audience',null,'What does a writer’s understanding of an audience’s beliefs, values and needs help the writer do?','Choose claims, evidence and appeals that this audience is likely to find reasonable.',['Avoid making any claim at all.','Guarantee that every reader will agree.'],'Knowing the audience lets a writer choose reasons it will weigh. It cannot guarantee agreement, and an argument still needs a claim.'],
 ['audience',null,'Which sentence names an audience’s value rather than a belief?','They care about fairness to every neighbor.',['They think the new bridge will open next year.','They expect the vote to be held on Tuesday.'],'A value is what people hold important, such as fairness. The other two are beliefs about what is or will be true.'],
 ['audience',null,'A writer addresses new voters who do not know where polling places are. Which need should the writer meet first?','Clear directions on where and when to vote.',['Praise for the writer’s own record.','A long history of voting law.'],'A need is something the audience requires to act or understand. These voters first need practical directions.'],
 ['audience','thor1','Thoreau writes for citizens who think prison is shameful. Which audience value does this sentence appeal to?','Justice, placed above reputation or comfort.',['Obedience to every law.','Loyalty to a king.'],'Thoreau turns the shame around: if the government is unjust, prison is the honorable place, so he asks readers to value justice over standing well with the state.'],
 ['audience','anth1','Anthony speaks to people who treat the Constitution as the nation’s foundation. Which belief of the audience does she build on?','That the nation was formed in the name of the people.',['That only property owners form a government.','That women have never been citizens.'],'She uses the audience’s own respect for “we, the people” and asks it to take those words at face value.'],
 ['audience','wash1','Washington is addressing citizens of a new republic. Which audience value does he assume?','That a self-governing people needs to be informed.',['That leaders should ignore public opinion.','That education is unimportant to a republic.'],'He ties the force of public opinion to its being enlightened, so he assumes his audience values self-government and sees knowledge as its support.'],
 ['audience','jeff1','Jefferson spoke in 1801, after a bitter election between parties. Which need of his audience does this sentence meet?','A call for unity after division.',['Proof that the election was invalid.','A reason to punish his opponents.'],'After a divided election, listeners needed reassurance that opponents shared basic principles.'],
 ['audience',null,'A writer persuades a town of retirees on fixed incomes to support a fictional bond. Which appeal fits that audience best?','Showing that the yearly cost for each household stays small.',['Stressing how exciting the new gym equipment will be for teenagers.','Quoting the slang that is popular on social media.'],'Retirees on fixed incomes care about cost, so a writer who addresses cost meets the audience’s need.'],
 ['audience',null,'An audience already agrees with the claim. What can the writer do?','Spend less time proving the basics and invite readers to act.',['Prove the claim from the start with long definitions.','Attack the readers for agreeing too easily.'],'When readers already agree, the writer can move on from proof to what the audience should do.'],
 ['audience',null,'A writer wants a town that treasures its traditions to support repairs to the festival hall. Which opening fits that audience?','For three generations this hall has gathered our families, and repairing it keeps that promise.',['Old buildings are a drain on any budget.','Nobody remembers why the hall was built.'],'The first opening appeals to the audience’s value of tradition. The others undercut it.'],
 ['audience','emer1','Emerson tells readers to trust themselves. Which audience value does this appeal to?','Independence of thought.',['Obedience to custom.','Loyalty to a political party.'],'The command to trust oneself speaks to readers who prize independent judgment.'],
 ['audience','tr1','Roosevelt told an audience of scholars that those who merely criticize do not count. What risk does that choice carry with such an audience?','Listeners who value careful criticism may feel the speaker is dismissing them.',['Scholars would have no interest in the topic.','The sentence has no connection to its audience.'],'A speaker who understands the audience weighs how its values may react. Scholars who prize criticism may bristle at this sentence.'],
 ['audience',null,'Which change shows a writer adapting to an audience’s needs?','Defining technical terms for readers who are new to the topic.',['Adding more technical terms to impress the readers.','Leaving out the claim so no one objects.'],'Readers new to a topic need terms explained. Piling on jargon or hiding the claim does not meet their needs.'],
 ['audience',null,'An audience holds a belief that conflicts with the writer’s claim. Which approach respects the belief and still argues the claim?','Acknowledge the belief, then explain why the evidence still supports the claim.',['Ignore the belief entirely.','Insult the people who hold it.'],'Acknowledging a belief earns a hearing, and the writer can then show why the evidence points elsewhere.'],
 ['audience',null,'Which clue most directly shows what a writer assumes the audience values?','The shared values the writer appeals to when giving reasons.',['How many paragraphs the text has.','Whether the title is short.'],'The values a writer appeals to in the reasons show what the writer thinks the audience cares about.'],
 ['audience','robo','Which audience need does the second sentence address?','Parents’ concern for student safety.',['Students’ wish for snacks.','The principal’s wish for a longer school day.'],'The sentence speaks to parents, who need to know the students will be supervised.'],
 ['audience',null,'A fictional writer cites cost savings to a budget committee and student safety to parents. What does this show?','The writer chose reasons to match what each audience values.',['The writer contradicts the claim.','The writer has no audience in mind.'],'Different audiences weigh different reasons, so a writer may offer the reasons each one values.'],
 ['audience','cj','Chief Joseph’s listeners were army officers who had been fighting his people. Which audience value does the sentence about the children appeal to?','Compassion for the suffering of the innocent.',['Pride in a military victory.','Fear of a new tax.'],'The detail of freezing children appeals to compassion and gives listeners a human reason to end the fighting.'],
 ['relation',null,'How is a claim related to the evidence that supports it?','The evidence is offered to show that the claim is reasonable or true.',['The evidence only restates the claim in other words.','The claim is only a summary of the evidence.'],'Evidence is offered to back a claim. If it only repeated the claim, it would prove nothing.'],
 ['relation','pool','Which sentence is the claim?','The pool should open an hour earlier.',['In a fictional log, 42 of the 60 morning swimmers waited outside for at least fifteen minutes.','Both sentences are claims.'],'The first sentence says what should be done. The second gives a count that is offered to support it.'],
 ['relation',null,'A writer claims that the school should add a late bus. Which evidence best supports it?','In a fictional poll, 90 students said they stay after school for clubs and have no ride home.',['Fictional fuel prices for buses rose 10 percent last year.','Most students already walk to school in the morning.'],'The poll shows a need for a late bus. The other two do not bear on that claim.'],
 ['relation',null,'Which pair shows a claim followed by fitting evidence?','Claim: Recess improves focus. Evidence: In a fictional study of 80 students, those with recess did better on attention tasks.',['Claim: Recess improves focus. Evidence: Recess lasts 20 minutes.','Claim: Recess improves focus. Evidence: Recess is the favorite time of many students.'],'Only the first evidence tests whether recess affects focus. The others describe recess without linking it to focus.'],
 ['relation',null,'Which statement is a claim rather than evidence?','The city should plant more trees.',['Last summer the fictional city recorded 31 days above 95 degrees.','A fictional survey counted 4,000 street trees.'],'“Should” signals a position that needs support. The other two are facts offered as support.'],
 ['relation','emer2','Emerson states this as a claim and gives no statistic in the sentence. What should a reader still look for?','Reasons or examples elsewhere in the essay that support the claim.',['Nothing, since a claim never needs support.','Only the author’s name.'],'A claim without support is only an assertion. A reader looks for the reasoning and examples around it.'],
 ['relation','meet','Does the evidence support the claim that most members attend?','Yes, because 18 of 24 is more than half.',['No, because 18 of 24 is less than half.','No, because the evidence is fictional.'],'18 of 24 is 75 percent, which is more than half. A fictional label only marks invented numbers; it does not stop them from supporting a fictional claim.'],
 ['relation','route','Does the evidence support the claim that the new route saves time for most riders?','No, because 11 of 30 is fewer than half.',['Yes, because 11 is a large number.','Yes, because the trial had 30 riders.'],'11 of 30 is about 37 percent, which is under half, so the trial does not show that most riders save time.'],
 ['relation','cj','Chief Joseph describes cold and freezing children. Which claim do these details most directly support?','That his people can no longer continue the fight.',['That the army has too few supplies.','That the winter will end soon.'],'The details of suffering are offered as reasons why the fighting should stop for his people.'],
 ['relation',null,'Why must evidence be relevant to the claim?','Evidence that does not bear on the claim cannot support it, however impressive it sounds.',['Because impressive numbers always prove a claim.','Because only one piece of evidence is allowed.'],'Relevance means the evidence actually bears on the claim. Impressive but unrelated facts leave the claim unsupported.'],
 ['relation','shelter','In this fictional sentence, which part is the evidence?','The shelter turned away 140 families last winter.',['The county should fund more beds.','Both parts are evidence.'],'“Because” introduces the evidence, and the claim is what the county should do.'],
 ['relation',null,'Can one claim have more than one piece of evidence?','Yes, several pieces of evidence, even of different kinds, can support one claim.',['No, each claim allows only one piece.','Only if they are all statistics.'],'Writers often combine statistics, examples and testimony to support a claim from several sides.'],
 ['relation','late','How does the evidence relate to the claim?','It contradicts the claim.',['It supports the claim.','It is unrelated to the claim.'],'If 9 of 20 buses were late, the bus line was not “always on time.”'],
 ['relation',null,'Which phrase most often signals that evidence is about to follow a claim?','“For instance”',['“Meanwhile”','“Nevertheless”'],'“For instance” introduces an example offered as support. The others shift time or contrast ideas.'],
 ['relation','wash2','What part of an argument is this sentence mainly?','A claim about what the nation should do.',['A statistic that proves a point.','An anecdote about a battle.'],'Washington recommends a course of action, so the sentence is a claim of policy that would need reasons.'],
 ['types','stat','Which kind of evidence is this?','A statistic from a survey.',['An anecdote.','Expert testimony.'],'A count taken from a survey is a statistic. It shows how many people in a group answered one way.'],
 ['types','anec','Which kind of evidence is this?','An anecdote, or short personal story.',['A statistic.','An analogy.'],'One neighbor’s experience told as a short story is an anecdote.'],
 ['types','expert','Which kind of evidence is this?','Expert testimony.',['A statistic from a survey.','A historical example.'],'The writer relies on a named person’s expertise in the subject.'],
 ['types','analogy','Which kind of evidence is this?','An analogy.',['A statistic.','A direct observation.'],'The sentence explains one thing by comparing it with another that readers know.'],
 ['types','history','Which kind of evidence is this?','A historical example.',['Expert testimony.','An analogy.'],'The writer points to something that happened in the past and draws on it.'],
 ['types','obs','Which kind of evidence is this?','A firsthand observation.',['Expert testimony.','A quotation from an authority.'],'The writer reports what he or she saw and counted personally.'],
 ['types',null,'A writer quotes a respected historian’s conclusion about a treaty. Which kind of evidence is this?','A quotation from an authority.',['An anecdote.','A statistic from a survey.'],'Quoting someone with relevant expertise supports a claim with their authority.'],
 ['types',null,'What makes expert testimony credible?','The expert’s relevant training or experience in the subject.',['The expert’s fame in an unrelated field.','The expert’s agreement with the writer.'],'An expert is believable on matters in which he or she is trained. Fame elsewhere or agreement alone is not expertise.'],
 ['types',null,'Which kind of evidence works best to help an audience feel what an issue means to real people?','An anecdote.',['A table of percentages.','A definition from a dictionary.'],'A story about a particular person lets readers imagine the issue, though it should be paired with broader evidence.'],
 ['types',null,'Which evidence is best for showing how widespread a problem is?','A statistic from a large, well-chosen sample.',['A story about one person’s bad day.','A quotation from a poem.'],'A representative count shows how common something is. One story shows only what happened once.'],
 ['types',null,'What does an analogy do, and not do?','It helps explain or suggest a point by likeness, but it does not prove the point on its own.',['It proves a claim as strongly as a controlled study.','It only works if the two things are identical.'],'An analogy clarifies by comparison. Because the two things always differ, it supports a claim less strongly than direct evidence.'],
 ['types',null,'Why can an anecdote alone be weak evidence for a broad claim?','One story may not be typical of what usually happens.',['Stories are never true.','Readers dislike personal stories.'],'A single case may be unusual. An anecdote works best beside broader evidence.'],
 ['types',null,'A writer claims that a fictional city’s summers are getting hotter. Which is the strongest choice of evidence?','Fictional temperature records for the last forty years.',['A story about one hot day.','A friend’s guess about the weather.'],'Records over time show a trend. One day or a guess cannot.'],
 ['types','anth1','Anthony supports her claim by pointing to the wording of the founding. Which kind of evidence is that?','A reference to a founding document.',['A personal anecdote.','A statistic from a survey.'],'She appeals to the words “we, the people” of the founding text to show who formed the Union.'],
 ['types','cj','Chief Joseph describes cold, missing blankets and freezing children. Which kind of evidence is this?','Specific details from firsthand knowledge.',['A statistic.','Expert testimony.'],'He names concrete conditions that he and his people were living in.'],
 ['types',null,'Which sentence is an example of expert testimony?','Dr. Omar Reyes, a fictional pediatrician, advises that young children need ten hours of sleep.',['My cousin says that he feels better after eight hours.','Sleep is a very common topic in magazines.'],'The first sentence names a person with relevant training who gives advice. The others are casual or irrelevant.'],
 ['types',null,'Which sentence offers a historical example?','In 1920 the fictional town of Alder passed a leash law, and complaints about loose dogs fell within a year.',['Dogs are friendly animals.','Many people like to walk dogs after dinner.'],'The first sentence points to a past event and its result.'],
 ['types',null,'Which sentence is an anecdote?','Last week my grandfather got lost on the way to the clinic because the road signs were gone.',['Road signs are made of metal.','Eight of ten fictional drivers said they like clear signs.'],'A short story about one person’s experience is an anecdote. The last option is a statistic.'],
 ['thesis',null,'What is a line of reasoning?','The sequence of claims and reasons through which an argument develops its thesis.',['A list of every source the writer read.','The first line of the introduction.'],'The line of reasoning is the path from claim to claim that leads the reader to the thesis.'],
 ['thesis',null,'Which thesis takes a position and gives a reason?','Schools should limit phone use in class because notifications interrupt learning.',['Phones are used in many schools.','This essay will talk about phones.'],'A thesis takes a position that can be disputed, and the “because” gives the reason.'],
 ['thesis','thor1','Which statement best paraphrases the claim in this sentence?','A just person should accept prison rather than support an unjust government.',['A just person should always obey the government.','Prison is the best place for every citizen.'],'Thoreau says that under an unjust government, the honorable place for a just person is in prison, and the next claims of his essay build on that.'],
 ['thesis','emer1','Which statement best paraphrases this claim?','Readers should rely on their own judgment.',['Readers should follow the crowd.','Readers should distrust strong feelings.'],'“Trust thyself” is a call to rely on one’s own judgment.'],
 ['thesis','wash1','Which line of reasoning links the two sentences?','Public opinion has force in this government, so it must be enlightened, so knowledge should be spread.',['Public opinion is weak, so leaders can ignore it.','Knowledge is costly, so citizens should have less of it.'],'Washington moves from the power of public opinion to its need for knowledge to the recommendation to promote institutions that spread it.'],
 ['thesis','topics','Which thesis do these three fictional topic sentences develop?','The city should fund a faster bus route because delays cost families income.',['Buses are a common form of transport.','Families should avoid missing work.'],'The first two sentences give causes, and the third states the position they lead to.'],
 ['thesis',null,'A student writes only the topic “Cell phones in school.” Which revision turns it into a defensible thesis?','Schools should limit phone use during class because notifications interrupt learning.',['Cell phones are in many schools.','This essay is about cell phones.'],'A thesis takes a position that others could dispute and gives a reason.'],
 ['thesis',null,'What is wrong with the thesis “The library has three floors”?','It states a fact that no one can dispute.',['It is too long.','It uses a persuasive word.'],'A thesis needs a position that could be argued with reasons. A plain fact leaves nothing to prove.'],
 ['thesis',null,'In a long argument, each body paragraph usually advances which of these?','A supporting claim that helps prove the thesis.',['A new thesis that replaces the old one.','A list of unrelated facts.'],'Each paragraph develops one step of the line of reasoning toward the thesis.'],
 ['thesis',null,'Which thesis qualifies its claim with a concession?','Although remote work saves commuting time, offices still help new employees learn.',['Remote work is always better.','Offices are the topic of this essay.'],'“Although” grants a fair point before stating the position, which shows awareness of other views.'],
 ['thesis',null,'How can a reader find a line of reasoning?','Trace how each paragraph’s claim leads to the next and back to the thesis.',['Count the sentences in each paragraph.','Read only the first and last words.'],'The line of reasoning is the progression of claims, so the reader follows how one leads to the next.'],
 ['thesis','anth2','Which claim about the Union’s purpose does Anthony make?','That it secured liberty for the whole people, women included.',['That it protected only men.','That it gave liberty to some and withheld it from others.'],'She says the Union was formed to secure liberty for “the whole people—women as well as men.”'],
 ['thesis','tr2','Which position do these lines argue for?','That credit belongs to those who act and struggle, not to those who only criticize.',['That critics deserve all the credit.','That the arena is a place to avoid.'],'Roosevelt praises the person in the arena who strives, in contrast to the critic.'],
 ['thesis',null,'A writer’s thesis changes halfway through the essay. What is the problem?','The line of reasoning is broken because the paragraphs no longer support one thesis.',['The essay has too many facts.','The essay uses a quotation.'],'A line of reasoning needs every claim to serve the same thesis.'],
 ['thesis',null,'Which transition best moves from a claim about cost to a related claim about safety?','In addition to saving money, the plan also protects children.',['Meanwhile, the weather was warm.','Unlike the plan, the bus has wheels.'],'A transition should show how the second claim relates to the first within the line of reasoning.'],
 ['thesis',null,'Which of these is a thesis with a reason?','The town should close Main Street on Saturdays because crowds make it unsafe for cars.',['Main Street is closed on Saturdays.','Many people shop on Main Street.'],'A thesis names a position and its reason. The others state facts.'],
 ['thesis',null,'Why is “Many people like music” a weak thesis?','Almost no one would disagree, so there is nothing to argue.',['It uses too many adjectives.','It is too specific.'],'A thesis must be a position a reasonable person could dispute.'],
 ['thesis','jeff1','Which line of reasoning does this sentence set up for Jefferson’s audience?','Opponents share basic principles, so the nation can unite.',['The losers should leave the country.','Principles do not matter in politics.'],'After a divided election, Jefferson argues that disagreement over opinions need not mean disagreement over principles.'],
 ['commentary',null,'What is the purpose of commentary?','To explain how and why the evidence supports the claim.',['To repeat the evidence in new words.','To introduce a new topic.'],'Commentary connects the evidence to the claim. Restating the evidence leaves the link unexplained.'],
 ['commentary',null,'Which words most often begin commentary?','“This shows that”',['“According to a survey,”','“In 1998,”'],'“This shows that” starts an explanation. The others usually introduce evidence.'],
 ['commentary','homework','Which commentary best links the evidence to the claim?','Since nearly three in four members improved, the club appears to give students real help with their work.',['The report counted 25 members in the club.','Libraries are quiet places that many people enjoy.'],'18 of 25 is 72 percent, and the first sentence explains what that means for the claim. The others restate or change the subject.'],
 ['commentary','trees','Which commentary best links the evidence to the claim?','Because the shaded sidewalk was cooler at the same hour, shade from trees likely lowers the heat people feel on the block.',['The shaded sidewalk measured 8 degrees cooler.','Trees also give birds a place to nest.'],'The first sentence explains why the measurement supports the claim. The others repeat the data or drift.'],
 ['commentary','start','Which commentary best links the evidence to the claim?','Fewer absences suggest that students were better able to arrive ready for class, which supports the idea that later starts help.',['The school started 45 minutes later and had 30 percent fewer absences.','Some schools have buses that run on different routes.'],'The first sentence explains how fewer absences bear on the claim and uses cautious wording. The others only repeat or change the subject.'],
 ['commentary','thor1','A writer claims that Thoreau ranks conscience above obedience to the state. Which sentence is the best commentary on this quotation?','By saying a just man’s place is in prison under an unjust government, Thoreau shows he ranks conscience above obedience.',['Thoreau wrote about prisons.','Prison was a common punishment in the 1840s.'],'The best commentary explains how the quotation proves the claim. The others restate it or add a loosely related fact.'],
 ['commentary','emer3','A writer claims that Emerson warns against conforming just to look consistent. Which sentence is the best commentary on this quotation?','By calling a foolish consistency the “hobgoblin of little minds,” Emerson suggests that clinging to old positions only to look consistent is a sign of small thinking.',['Emerson uses the word “hobgoblin.”','Emerson wrote many essays.'],'The best commentary explains what the wording shows. The others only note a word or a fact about the author.'],
 ['commentary','wash1','A writer claims that Washington linked self-government to education. Which sentence is the best commentary on this quotation?','By tying the force of public opinion to its being enlightened, Washington implies that a self-governing people must be educated.',['Washington gave his Farewell Address in 1796.','The quotation has two sentences.'],'Commentary explains how the words support the claim. The others state facts that do not.'],
 ['commentary','jeff1','A writer claims that Jefferson tried to calm the divide after the election of 1800. Which sentence is the best commentary on this quotation?','By separating differences of opinion from differences of principle, Jefferson reminds listeners that opponents still share the nation’s basic aims.',['Jefferson was the third president.','Jefferson’s speech was given in the spring.'],'The best commentary shows how the sentence works to calm the divide. The others give facts that do not explain it.'],
 ['commentary',null,'What weakens commentary?','Merely repeating the evidence in different words.',['Explaining how the evidence relates to the claim.','Using precise words.'],'Commentary that only restates the evidence does not tell the reader why it matters.'],
 ['commentary',null,'A paragraph has a claim and two quotations but nothing else. What is missing?','An explanation of how the quotations prove the claim.',['A longer title.','More quotations of the same kind.'],'Evidence without commentary leaves the reader to guess why it matters.'],
 ['commentary','read','Which commentary is accurate?','The average rose by 15 minutes, a 75 percent increase.',['The average rose by 15 minutes, a 43 percent increase.','The average rose by 55 minutes, a 175 percent increase.'],'35 − 20 = 15 minutes, and 15 ÷ 20 = 0.75, which is 75 percent. Dividing by 35 is the usual slip.'],
 ['commentary','attend','Which commentary is accurate? Round to the nearest percent.','Attendance rose by 12 students a day, a 15 percent increase.',['Attendance rose by 12 students a day, a 13 percent increase.','Attendance rose by 12 students a day, a 12 percent increase.'],'92 − 80 = 12, and 12 ÷ 80 = 0.15, which is 15 percent. Dividing by 92 gives 13 percent.'],
 ['commentary',null,'A fictional survey of 60 students in one class found that 45 prefer morning tests. Which commentary correctly limits what the evidence shows?','The survey shows what these 60 students think, which suggests but does not prove a school-wide view.',['The survey proves that every student in the world prefers morning tests.','The survey shows nothing at all.'],'Good commentary says no more than the evidence can support. A single class is a small sample.'],
 ['commentary',null,'Which sentence summarizes the evidence instead of commenting on it?','The report states that 70 percent of fictional residents recycle.',['This high rate suggests that most residents already see recycling as normal.','That rate matters because new programs are easier to start when people are willing.'],'A summary reports what the evidence says. Commentary says what it shows or why it matters.'],
 ['commentary','cj','A writer claims that Chief Joseph persuades by naming the human cost of continuing the war. Which sentence is the best commentary on this quotation?','By naming the children’s suffering, Joseph gives listeners a concrete reason to see why fighting on is impossible.',['Joseph mentions blankets.','Joseph spoke in October.'],'The best commentary explains how the details persuade. The others only restate a detail or give a date.'],
 ['commentary','anth1','A writer claims that Anthony uses the nation’s founding words to argue that women are included. Which sentence is the best commentary on this quotation?','By ruling out “white male citizens” and “male citizens” and ending with “the whole people,” she shows that the founding words exclude no group.',['Anthony was a speaker in 1873.','The sentence contains many semicolons.'],'The best commentary explains how the wording supports the claim. The others note unrelated facts.'],
 ['commentary',null,'In the sentence “The lake’s temperature rose three degrees, which means the water now holds less oxygen,” what is the commentary?','The part after “which means” that explains what the change shows.',['The part before the comma that gives the measurement.','There is no commentary in the sentence.'],'The measurement is the evidence, and the clause after “which means” explains its significance.'],
 ['commentary',null,'Which question best helps a writer produce commentary?','“So what does this evidence show about my claim?”',['“How many facts can I fit in this paragraph?”','“What is the longest quotation I can find?”'],'Asking what the evidence shows pushes the writer to explain the link.'],
 ['evaluate',null,'Which makes a source more credible on a medical question?','It is written by a physician and reviewed by other experts.',['It was shared widely on social media.','It was written by a famous actor.'],'Credibility comes from relevant expertise and checking by others. Popularity and fame are not enough.'],
 ['evaluate','sleep','What is the main weakness of the evidence?','The sample is too small and unrepresentative.',['The sample is too large.','The sentence has no verb.'],'Three friends cannot show what all students at a school experience.'],
 ['evaluate','poll','Which claim does the survey best support? Round to the nearest percent.','About 25 percent of those surveyed walk to work.',['About 75 percent of those surveyed walk to work.','About 4 percent of those surveyed walk to work.'],'125 ÷ 500 = 0.25, which is 25 percent. Random selection also makes the sample more representative.'],
 ['evaluate','lunchsurvey','Why is this a weak sample for a claim about all students?','It reaches only students who already buy lunch.',['It is too long.','It uses a survey, and surveys are never useful.'],'A sample must represent the whole group. This one leaves out students who bring lunch or skip it.'],
 ['evaluate','drivers','Which flaw does this show?','A hasty generalization from too little evidence.',['An appeal to the writer’s credentials.','A fair summary of the data.'],'Two drivers cannot show what all drivers in a city are like.'],
 ['evaluate','icecream','What is wrong with the writer’s claim?','Two things that rise together may both be caused by a third factor, such as hot weather.',['Ice cream is not sold in July.','A claim must always include a statistic.'],'A correlation does not show cause. Hot weather can explain both the ice cream sales and the swimming.'],
 ['evaluate',null,'A claim about how teenagers use phones today cites a fictional survey from 1998. What is the weakness?','The evidence may be out of date.',['The survey was too recent.','Old evidence is always the best.'],'Phone use has changed, so older evidence may not describe the present.'],
 ['evaluate',null,'Which evidence is irrelevant to the claim that a bridge needs repair?','The bridge was painted blue in 1960.',['An inspection found cracks in the supports.','Trucks heavier than the limit cross the bridge daily.'],'Paint color does not bear on structural safety. Cracks and overweight trucks do.'],
 ['evaluate',null,'Evidence from one town supports only a limited claim. Which claim fits?','In this town, most residents favor the park.',['Everywhere, most people favor parks.','Nobody opposes parks.'],'A claim should not go beyond what the evidence covers.'],
 ['evaluate','cj','The words are recorded by others from an interpreter. How should that affect confidence in the exact wording?','Treat the exact wording with some caution, since it passed through a translator and a recorder.',['The wording is certainly word for word.','The words have no meaning.'],'Recording by others introduces the chance of small differences, so historians note that printings vary.'],
 ['evaluate','emer4','As evidence that misunderstood people are great, what is a limit of this sentence?','It does not show that every misunderstood person is great.',['It proves that everyone is great.','It is too long to be evidence.'],'“Great people are misunderstood” does not mean “misunderstood people are great.” The converse does not follow.'],
 ['evaluate',null,'Which source is most appropriate for a historical claim about voting rights in 1873?','The text of a speech from that year or a scholarly history.',['A blog post with no sources.','A rumor that people repeat.'],'Primary texts and scholarly histories can be checked. The others cannot.'],
 ['evaluate',null,'A writer finds evidence that complicates the claim. What is the best response?','Qualify the claim or explain why it still holds.',['Leave the evidence out.','Change the data to match.'],'Fair arguments face complicating evidence. Hiding or changing it is dishonest.'],
 ['evaluate','sample','What share of the 3,000 voters is 12 people? Round to the nearest tenth of a percent.','0.4 percent',['4 percent','0.04 percent'],'12 ÷ 3,000 = 0.004, which is 0.4 percent. That is far too small a share to show what most voters favor.'],
 ['evaluate',null,'A company’s own fictional study says its product is the best. Why should a reader be careful?','The company profits from the result, so independent confirmation helps.',['Companies never do studies.','A study cannot be trusted if it has numbers.'],'A source with a stake in the result may be biased. Independent studies add confidence.'],
 ['evaluate',null,'Which evidence is the most specific?','In a fictional log, 37 of 120 students were late at least once in October.',['Many students were late.','Lateness is a problem.'],'Specific counts, dates and groups give the reader something to check. Vague statements do not.'],
 ['evaluate',null,'When is evidence that only appeals to feelings a problem?','When it takes the place of the facts the claim needs.',['When it mentions people.','When it is a story.'],'Emotional appeals can help, but they cannot replace the facts a claim depends on.'],
 ['evaluate',null,'How can a writer check whether one anecdote is typical?','Look for broader data on how common the situation is.',['Retell the anecdote more dramatically.','Assume it is typical because it is vivid.'],'Broader data shows whether a story represents a pattern.']];
/* The Try-it questions in pool form; the generator skips them. */
const TRY=['Fictional passage: “To the senior center: our free ride to the clinic leaves from the front door, with a helper to carry your bags, so no one has to walk far.” Which audience need does the writer meet? A: Easy, safe travel for older riders, B: A wish for faster internet, C: Cheaper concert tickets. Answer A, B or C.',
 'Fictional passage: “Dr. Imani Cole, a fictional nutrition scientist with twenty years of research, advises adding vegetables to school lunches.” Which kind of evidence is this? A: A statistic, B: Expert testimony, C: An analogy. Answer A, B or C.',
 'Fictional passage: Claim: The school garden teaches responsibility. Evidence: In a fictional report, 16 of 20 students watered their plants every day. Which sentence is the best commentary? A: The report counted 20 students, B: Gardens grow many kinds of vegetables, C: Since most students cared for their plants daily, the garden appears to build responsibility. Answer A, B or C.'];
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
export default {
id:'language-h-ap-lang-claims-and-evidence',subject:'language',level:5,grade:9,standard:'AP English Language and Composition Course and Exam Description (College Board), Unit 2: Big Ideas RHS, CLE and REO',
title:'Claims and Evidence',
goal:'Read an argument as a writer shaping reasons for an audience: see how it meets the audience’s beliefs, values and needs; separate claims from the evidence that supports them; name the kinds of evidence; follow the thesis and the line of reasoning; write commentary that explains how evidence supports a claim; and judge whether the evidence is relevant, sufficient and credible.',
points:20,
skills:{audience:'Audience: beliefs, values and needs',relation:'Claims and evidence',types:'Kinds of evidence',thesis:'Thesis and line of reasoning',commentary:'Commentary',evaluate:'Judging evidence'},
outline:[['RHS (audience)','Explain how an argument speaks to an audience’s beliefs, values and needs',['audience']],['CLE (claims and evidence)','Identify claims and the evidence that supports them, and how they relate',['relation']],['CLE (types of evidence)','Identify the kinds of evidence and how each supports a claim',['types']],['CLE (thesis and line of reasoning)','Identify a thesis and the line of reasoning that develops it',['thesis']],['REO (commentary)','Explain how commentary links evidence to a claim',['commentary']],['CLE (judging evidence)','Judge whether evidence is relevant, sufficient and credible',['evaluate']]],
steps:[
 {skill:'audience',say:'A writer shapes an argument for the people who will read it. An audience has beliefs, which it holds to be true, values, which it holds to be important, and needs, which it requires in order to understand or act. A good writer asks all three: what do these readers already accept, what do they care about, and what do they still lack?',pic:board('Beliefs, values, needs',['Belief: what readers hold to be true','Value: what readers hold to be important','Need: what readers still require','Then choose reasons that fit all three'],['"the bridge is safe"','"fairness matters"','"clear directions"','fit the audience'])},
 {skill:'audience',say:'Context shows an audience. Washington spoke to citizens of a young republic, Jefferson to a country divided by an election, Thoreau to neighbors who respected the law, Anthony to people who revered the Constitution, Chief Joseph to officers ending a war, and Roosevelt to scholars. Each speaker chose reasons that the listeners were likely to weigh, which is how you can read the audience back out of the text.',pic:{t:'timeline',events:['1796 Washington','1801 Jefferson','1849 Thoreau','1873 Anthony','1877 Chief Joseph','1910 Roosevelt']}},
 {skill:'audience',say:'The same claim can be built in different ways for different readers. For a skeptical audience the writer may acknowledge doubts before answering them. For readers who already agree, the writer can spend less time on proof and more on action. Look at the examples a writer chooses and the values they flatter; they show whom the writer thinks is listening.',pic:pass('Fictional: one request, two audiences',['To the budget committee: “The new bike racks will save the school money, because fewer bikes will need replacing.”','To parents: “The new bike racks will keep students’ bikes safe while they study.”']),
  check:{prompt:tryIt(TRY[0]),answer:'A',options:['A','B','C'],hint:'The writer mentions a ride, a helper and a short walk. Which need do older riders have?',pic:pass('Fictional passage',['To the senior center: our free ride to the clinic leaves from the front door, with a helper to carry your bags, so no one has to walk far.'])}},
 {skill:'relation',say:'A claim is a statement that needs support, and evidence is what is offered to support it. Between them sits commentary, the writer’s explanation of how the evidence backs the claim. Read an argument by finding the claim first, then each piece of evidence, then asking whether the writer explains the link. A strong paragraph has all three, in an order the reader can follow.',pic:flow('Claim, evidence, commentary',[['Claim','What is to be accepted'],['Evidence','What is offered'],['Commentary','Why it supports the claim']])},
 {skill:'relation',say:'Evidence supports a claim only if it is relevant and the numbers actually say what the claim says. Take the fictional claim that most club members voted, with 14 of 20 members voting. Divide, 14 ÷ 20 = 0.70, which is 70 percent, so more than half voted and the evidence fits. If only 9 of 25 had voted, 9 ÷ 25 = 0.36, which is 36 percent, and a claim of “most” would fail.',pic:board('Does the evidence fit the claim?',['Claim: most club members voted','Evidence: 14 of 20 members voted','14 ÷ 20 = 0.70, or 70 percent','70 percent is more than half, so it fits'],['"most" means over half','fictional count','divide','compare with 50 percent'])},
 {skill:'types',say:'Evidence comes in kinds. Statistics count or measure things, and examples or anecdotes show a case. Expert testimony and quotations bring in an authority, analogies explain by likeness, historical examples point to the past, and firsthand observation reports what the writer saw. No kind is best everywhere: the writer picks the kind that suits the claim and the audience.',pic:grid('Kinds of evidence',['Statistic','Anecdote','Expert testimony','Analogy','Historical example','Observation'])},
 {skill:'types',say:'Each kind has a strength and a limit. A statistic shows how common something is but may feel cold. An anecdote makes an issue real but may not be typical. Expert testimony lends authority only inside the expert’s field. An analogy explains but does not prove, because the two things always differ. Name the kind first, then say what it does for this claim.',pic:pass('Fictional: three kinds of evidence',['Statistic: “In a fictional poll of 300 riders, 210 wanted a Sunday bus.”','Anecdote: “My aunt waited an hour for a bus last Sunday.”','Analogy: “A town without a Sunday bus is like a library that closes on weekends.”']),
  check:{prompt:tryIt(TRY[1]),answer:'B',options:['A','B','C'],hint:'The writer names a person with a title and years of research. What does that person provide?',pic:pass('Fictional passage',['Dr. Imani Cole, a fictional nutrition scientist with twenty years of research, advises adding vegetables to school lunches.'])}},
 {skill:'types',say:'A statistic needs to be read carefully. In the fictional survey shown, 190 of 250 residents supported longer library hours. Divide, 190 ÷ 250 = 0.76, so 76 percent supported it. The percent tells how widespread support is among those surveyed, and who was surveyed and how many matter as much as the percent.',pic:bars('Fictional survey of 250 residents',[['Support',190],['Do not support',60]])},
 {skill:'thesis',say:'The thesis is the central claim, and the line of reasoning is the sequence of supporting claims that leads the reader to it. Thoreau, for example, asks whether to obey unjust laws, to work to amend them, or to break them at once. His essay then argues that a person should refuse to take part in a wrong rather than wait for a majority to end it. Each step prepares the next.',pic:pass('A question Thoreau asks, 1849',['Unjust laws exist: shall we be content to obey them, or shall we endeavor to amend them, and obey them until we have succeeded, or shall we transgress them at once?'])},
 {skill:'thesis',say:'You can see a line of reasoning by tracing the claims. A thesis states the position, supporting claims give the reasons, and each body paragraph develops one of them. If a paragraph does not serve the thesis, the line of reasoning breaks. When you read, ask how each claim leads to the next and how it returns to the thesis.',pic:flow('A line of reasoning',[['Claim 1','Reason one'],['Claim 2','Reason two'],['Thesis','The position proved']])},
 {skill:'thesis',say:'To write a thesis, start from a topic and take a position that someone could dispute, then add a reason. The topic “school bus safety” becomes “Every bus should have seat belts because they prevent injuries.” A qualified thesis uses a word like although to grant a fair point, which shows fairness. Test each draft by asking whether a reasonable person could disagree.',pic:board('From topic to thesis',['Topic: school bus safety','Position: every bus should have seat belts','Reason: they prevent injuries','Thesis: add the reason to the position'],['a subject','arguable','because','position and reason'])},
 {skill:'commentary',say:'Commentary explains how evidence supports the claim. Take the claim that Emerson urges readers to rely on their own judgment, with the evidence “Insist on yourself; never imitate.” The commentary says why: the command to never imitate tells readers to reject copying others, so it supports the call for independent judgment. A good commentary names the key words of the evidence and says what they show.',pic:board('Evidence and commentary',['Claim: Emerson urges independent judgment','Evidence: “Insist on yourself; never imitate.”','Commentary: “never imitate” rejects copying others','So the evidence supports the claim'],['the point','Self-Reliance, 1841','explain the words','link back'])},
 {skill:'commentary',say:'Commentary is not summary. Summary says what the evidence is, and commentary says why it matters. Compare these two for the fictional claim that a program raised reading time: “The average rose from 20 to 25 minutes” is evidence, and “That is a gain of 5 minutes, or 25 percent, so students are reading more” is commentary. Check the numbers, then say what they mean.',pic:board('Summary or commentary?',['Evidence: the average rose from 20 to 25 minutes','25 − 20 = 5 minutes','5 ÷ 20 = 0.25, or 25 percent','Commentary: students are reading more'],['a fact','difference','percent change','what it shows']),
  check:{prompt:tryIt(TRY[2]),answer:'C',options:['A','B','C'],hint:'Which sentence explains what the evidence means for the claim instead of repeating it?',pic:pass('Fictional passage',['Claim: The school garden teaches responsibility.','Evidence: In a fictional report, 16 of 20 students watered their plants every day.'])}},
 {skill:'evaluate',say:'Judge evidence with a few questions. Is it relevant, so that it bears on the claim? Is it sufficient, so that there is enough of it and it covers the claim? Is the source credible, with the right expertise and no stake in the result? Is it current and specific? A claim about all students needs more than three friends, and a claim about the present needs recent evidence.',pic:board('Is the evidence good?',['Relevant: does it bear on the claim?','Sufficient: is there enough, and enough kinds?','Credible: is the source trustworthy?','Current and specific: can it be checked?'],['fits','sample size','expertise','details'])},
 {skill:'evaluate',say:'Sample size matters. In this fictional picture, 8 of 10 people (80 percent) agree in a tiny sample, and 550 of 1,000 (55 percent) agree in a large one. The small sample shows a higher percent but tells you less, because a few people can change it a lot. When a claim is broader than the evidence, narrow the claim or add evidence.',pic:bars('Fictional: percent who agree',[['10 people',80],['1,000 people',55]])},
 {skill:'evaluate',summary:true,say:'Tie the unit together with one habit. Ask who the audience is and what it believes, values and needs. Find the claim and the thesis, and the evidence offered for each. Name the kind of evidence, check that it is relevant, sufficient and credible, and look for commentary that explains the link. If a step is missing, say what the writer should add.',pic:flow('Reading evidence: the habit',[['Audience','Beliefs, values, needs'],['Evidence','Fits, enough, credible'],['Commentary','Explains the link']])}],
progression:{requires:['language-h-ap-lang-rhetorical-situation'],operations:2,demand:'Read arguments closely for how they use evidence: see how a text meets its audience’s beliefs, values and needs, separate claims from evidence, name the kinds of evidence, follow the thesis and line of reasoning, write commentary that links evidence to a claim, and judge whether evidence is relevant, sufficient and credible.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 ROWS.forEach(([skill,key,q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  if(!key){put(skill,`${q} ${c.text}. ${ask(c.n)}`,c.letter,null/* 25 Oct: no picture; it only repeated the question in tiny type */,why,[right,dot(right)]);return;}
  const [src,lines]=P(key),text=lines.join(' ');
  put(skill,`${src}: “${text}” ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(src,lines),why,[right,dot(right)]);});
}};
